#!/usr/bin/env bash
# compare-manifests.sh
# Compare manifests generated by cdk8s and nixidy for equivalence verification
# Part of: Feature 114 - nixidy migration
#
# Usage:
#   ./scripts/compare-manifests.sh [--app APP_NAME] [--env ENV_TYPE] [--verbose]
#
# Options:
#   --app APP_NAME   Compare specific application (default: all pilot apps)
#   --env ENV_TYPE   Environment type: kind, talos (default: kind)
#   --verbose        Show detailed diff output
#   --help           Show this help message

set -euo pipefail

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Default values
APP_NAME=""
ENV_TYPE="kind"
VERBOSE=false
PILOT_APPS=("namespace" "backstage" "keycloak" "postgres" "redis")

# Directories
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
CDK8S_DIR="${REPO_ROOT}/cdk8s"
NIXIDY_DIR="${REPO_ROOT}/nixidy"
TMP_DIR="${REPO_ROOT}/.manifest-compare"

# Help function
show_help() {
    head -20 "$0" | tail -18 | sed 's/^# //'
    exit 0
}

log_info() {
    echo -e "${BLUE}[INFO]${NC} $1"
}

log_success() {
    echo -e "${GREEN}[PASS]${NC} $1"
}

log_warning() {
    echo -e "${YELLOW}[WARN]${NC} $1"
}

log_error() {
    echo -e "${RED}[FAIL]${NC} $1"
}

# Parse command line arguments
while [[ $# -gt 0 ]]; do
    case $1 in
        --app)
            APP_NAME="$2"
            shift 2
            ;;
        --env)
            ENV_TYPE="$2"
            shift 2
            ;;
        --verbose)
            VERBOSE=true
            shift
            ;;
        --help|-h)
            show_help
            ;;
        *)
            log_error "Unknown option: $1"
            show_help
            ;;
    esac
done

# Validate environment type
if [[ ! "$ENV_TYPE" =~ ^(kind|talos|hub)$ ]]; then
    log_error "Invalid environment type: $ENV_TYPE (must be kind, talos, or hub)"
    exit 1
fi

# Create temp directory
mkdir -p "${TMP_DIR}"
log_info "Using temp directory: ${TMP_DIR}"

# Build cdk8s manifests
build_cdk8s() {
    log_info "Building cdk8s manifests for ${ENV_TYPE}..."

    cd "${CDK8S_DIR}"

    # Set cluster type
    export CLUSTER_TYPE="${ENV_TYPE}"

    # Run synthesis
    if npm run synth 2>&1 | tee "${TMP_DIR}/cdk8s-build.log"; then
        log_success "cdk8s build completed"
    else
        log_error "cdk8s build failed. See ${TMP_DIR}/cdk8s-build.log"
        return 1
    fi

    cd "${REPO_ROOT}"
}

# Build nixidy manifests
build_nixidy() {
    log_info "Building nixidy manifests for ${ENV_TYPE}..."

    cd "${NIXIDY_DIR}"

    # Build using nixidy
    if nix build ".#nixidyEnvs.x86_64-linux.${ENV_TYPE}.config.build" -o "${TMP_DIR}/nixidy-result" 2>&1 | tee "${TMP_DIR}/nixidy-build.log"; then
        log_success "nixidy build completed"
    else
        log_error "nixidy build failed. See ${TMP_DIR}/nixidy-build.log"
        return 1
    fi

    cd "${REPO_ROOT}"
}

# Normalize YAML for comparison (remove non-semantic differences)
normalize_yaml() {
    local file="$1"
    local output="$2"

    # Use yq to:
    # 1. Sort keys alphabetically
    # 2. Remove empty fields
    # 3. Normalize whitespace
    # 4. Remove metadata that differs between tools (like generation timestamps)
    yq eval 'sort_keys(..) | del(.metadata.generation) | del(.metadata.creationTimestamp) | del(.metadata.resourceVersion) | del(.metadata.uid) | del(.status)' "$file" > "$output" 2>/dev/null || cat "$file" > "$output"
}

# Compare manifests for a single app
compare_app() {
    local app_name="$1"
    local differences=0

    log_info "Comparing manifests for: ${app_name}"

    # Paths
    local cdk8s_app_dir="${CDK8S_DIR}/dist/${app_name}/manifests"
    local nixidy_app_dir="${TMP_DIR}/nixidy-result/${app_name}"

    # Check if cdk8s app exists
    if [[ ! -d "$cdk8s_app_dir" ]]; then
        log_warning "cdk8s app not found: ${app_name} (might not exist in current build)"
        return 0
    fi

    # Check if nixidy app exists
    if [[ ! -d "$nixidy_app_dir" ]]; then
        log_warning "nixidy app not found: ${app_name}"
        return 1
    fi

    # Create normalized directories
    local cdk8s_normalized="${TMP_DIR}/normalized/cdk8s/${app_name}"
    local nixidy_normalized="${TMP_DIR}/normalized/nixidy/${app_name}"
    mkdir -p "$cdk8s_normalized" "$nixidy_normalized"

    # Normalize cdk8s manifests
    for file in "${cdk8s_app_dir}"/*.yaml; do
        if [[ -f "$file" ]]; then
            local basename=$(basename "$file")
            normalize_yaml "$file" "${cdk8s_normalized}/${basename}"
        fi
    done

    # Normalize nixidy manifests
    for file in "${nixidy_app_dir}"/*.yaml; do
        if [[ -f "$file" ]]; then
            local basename=$(basename "$file")
            normalize_yaml "$file" "${nixidy_normalized}/${basename}"
        fi
    done

    # Compare file lists
    local cdk8s_files=$(ls "${cdk8s_normalized}" 2>/dev/null | sort)
    local nixidy_files=$(ls "${nixidy_normalized}" 2>/dev/null | sort)

    # Check for missing files
    for file in $cdk8s_files; do
        if [[ ! -f "${nixidy_normalized}/${file}" ]]; then
            log_warning "File missing in nixidy: ${file}"
            ((differences++)) || true
        fi
    done

    for file in $nixidy_files; do
        if [[ ! -f "${cdk8s_normalized}/${file}" ]]; then
            log_warning "Extra file in nixidy: ${file}"
            ((differences++)) || true
        fi
    done

    # Compare file contents
    for file in $cdk8s_files; do
        if [[ -f "${nixidy_normalized}/${file}" ]]; then
            if ! diff -q "${cdk8s_normalized}/${file}" "${nixidy_normalized}/${file}" > /dev/null 2>&1; then
                log_warning "Content differs: ${file}"
                ((differences++)) || true

                if [[ "$VERBOSE" == "true" ]]; then
                    echo "--- Differences in ${file} ---"
                    diff -u "${cdk8s_normalized}/${file}" "${nixidy_normalized}/${file}" || true
                    echo ""
                fi
            fi
        fi
    done

    if [[ $differences -eq 0 ]]; then
        log_success "${app_name}: No semantic differences"
        return 0
    else
        log_error "${app_name}: ${differences} difference(s) found"
        return 1
    fi
}

# Generate comparison report
generate_report() {
    local report_file="${TMP_DIR}/comparison-report.md"
    local total_apps=0
    local passed_apps=0
    local failed_apps=0

    echo "# Manifest Comparison Report" > "$report_file"
    echo "" >> "$report_file"
    echo "**Generated:** $(date -Iseconds)" >> "$report_file"
    echo "**Environment:** ${ENV_TYPE}" >> "$report_file"
    echo "" >> "$report_file"
    echo "## Summary" >> "$report_file"
    echo "" >> "$report_file"
    echo "| Application | Status | Notes |" >> "$report_file"
    echo "|------------|--------|-------|" >> "$report_file"

    for app in "${APPS_TO_COMPARE[@]}"; do
        ((total_apps++)) || true
        if compare_app "$app" 2>/dev/null; then
            echo "| ${app} | :white_check_mark: PASS | Manifests equivalent |" >> "$report_file"
            ((passed_apps++)) || true
        else
            echo "| ${app} | :x: FAIL | See differences below |" >> "$report_file"
            ((failed_apps++)) || true
        fi
    done

    echo "" >> "$report_file"
    echo "## Results" >> "$report_file"
    echo "" >> "$report_file"
    echo "- **Total Applications:** ${total_apps}" >> "$report_file"
    echo "- **Passed:** ${passed_apps}" >> "$report_file"
    echo "- **Failed:** ${failed_apps}" >> "$report_file"
    echo "" >> "$report_file"

    log_info "Report written to: ${report_file}"

    return $failed_apps
}

# Main execution
main() {
    log_info "Starting manifest comparison for environment: ${ENV_TYPE}"

    # Determine which apps to compare
    if [[ -n "$APP_NAME" ]]; then
        APPS_TO_COMPARE=("$APP_NAME")
    else
        APPS_TO_COMPARE=("${PILOT_APPS[@]}")
    fi

    log_info "Apps to compare: ${APPS_TO_COMPARE[*]}"

    # Check if yq is available
    if ! command -v yq &> /dev/null; then
        log_error "yq is required but not installed. Install with: nix-env -iA nixpkgs.yq-go"
        exit 1
    fi

    # Build both systems
    build_cdk8s
    build_nixidy

    # Compare manifests
    local failed=0
    for app in "${APPS_TO_COMPARE[@]}"; do
        if ! compare_app "$app"; then
            ((failed++)) || true
        fi
    done

    # Summary
    echo ""
    log_info "========================================="
    log_info "Comparison Complete"
    log_info "========================================="

    if [[ $failed -eq 0 ]]; then
        log_success "All ${#APPS_TO_COMPARE[@]} applications passed equivalence check"
        exit 0
    else
        log_error "${failed}/${#APPS_TO_COMPARE[@]} applications have differences"
        exit 1
    fi
}

main "$@"
